const header = 'cluster\tnamespace\tpolicy\trule\tresult\tmessage\tresources';
const namespaces = new Map();

for (const { json } of $input.all()) {
  const rows = String(json.stdout || '').trim().split('\n');
  const headerIndex = rows.indexOf(header);
  if (headerIndex < 0) continue;

  for (const row of rows.slice(headerIndex + 1)) {
    const [cluster, namespace] = row.split('\t');
    if (cluster && namespace) namespaces.set(`${cluster}/${namespace}`, { cluster, namespace });
  }
}

return [{ json: { misconfiguredNamespaces: [...namespaces.values()] } }];

return [{
  json: {
    accessToken: String($json.stdout || '').trim(),
    misconfiguredNamespaces: $('Gather Misconfigured Namespaces').first().json.misconfiguredNamespaces,
  },
}];

const { accessToken, misconfiguredNamespaces = [] } = $input.first().json;
const products = new Map();

for (const finding of misconfiguredNamespaces) {
  const licencePlate = String(finding.namespace).slice(0, 6);
  if (!products.has(licencePlate)) products.set(licencePlate, []);
  products.get(licencePlate).push(finding);
}

return [...products].map(([licencePlate, namespaces]) => ({
  json: { accessToken, licencePlate, namespaces },
}));

const lookups = $('Build Registry Lookup Items').all();

return $input.all().map((item, index) => {
  const response = JSON.parse(item.json.stdout);
  if (!response.success || !response.data) {
    throw new Error(`Registry lookup failed for ${lookups[index].json.licencePlate}`);
  }

  const product = response.data;
  const contacts = [
    ['projectOwner', product.projectOwner],
    ['primaryTechnicalLead', product.primaryTechnicalLead],
    ['secondaryTechnicalLead', product.secondaryTechnicalLead],
  ]
    .filter(([, contact]) => contact)
    .map(([role, contact]) => ({
      role,
      name: [contact.firstName, contact.lastName].filter(Boolean).join(' '),
      email: contact.email,
    }));

  return {
    json: {
      licencePlate: lookups[index].json.licencePlate,
      productName: product.name,
      contacts,
      namespaces: lookups[index].json.namespaces,
    },
  };
});
